"use client";

import "./dialog.css";

import {
  useEffect,
  useRef,
  type ComponentProps,
  type ReactNode,
  type Ref,
} from "react";
import { Button, type ButtonVariant } from "./button";
import { cx } from "./cx";

export type DialogProps = Omit<ComponentProps<"dialog">, "open"> & {
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
};

export type DialogTitleProps = ComponentProps<"h2">;

export type DialogCloseProps = {
  children?: ReactNode;
  variant?: ButtonVariant | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
};

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === "function") {
    ref(value);
    return;
  }
  if (ref) ref.current = value;
}

export function Dialog({
  open,
  onOpenChange,
  className,
  onClose,
  ref: forwardedRef,
  ...rest
}: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const node = ref.current;
    if (!node || open === undefined) return;
    if (open && !node.open) node.showModal();
    if (!open && node.open) node.close();
  }, [open]);

  return (
    <dialog
      {...rest}
      ref={(node) => {
        ref.current = node;
        assignRef(forwardedRef, node);
      }}
      className={cx("ns-dialog", className)}
      onClose={(event) => {
        onClose?.(event);
        onOpenChange?.(false);
      }}
    />
  );
}

export function DialogTitle({ className, ...rest }: DialogTitleProps) {
  return <h2 className={cx("ns-dialog__title", className)} {...rest} />;
}

export function DialogClose({
  children = "Close",
  variant = "outline",
  disabled,
  className,
}: DialogCloseProps) {
  return (
    <form method="dialog">
      <Button
        variant={variant}
        type="submit"
        {...(disabled ? { disabled: true } : {})}
        {...(className ? { className } : {})}
      >
        {children}
      </Button>
    </form>
  );
}

export function DialogActions({ children }: { children: ReactNode }) {
  return <div className="ns-dialog__actions">{children}</div>;
}

@layer components {
  .ns-dialog {
    width: min(28rem, calc(100% - var(--space-10, 1.86rem)));
    max-height: calc(100% - var(--space-10, 1.86rem));
    margin: auto;
    padding: var(--space-8, 1.19rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 12%, transparent));
    border-radius: var(--radius, 0.4rem);
    background: var(--bg-overlay, var(--bg, #fff));
    color: var(--text-body, #444);
    box-shadow: var(--raise);
  }

  .ns-dialog::backdrop {
    background: color-mix(in srgb, var(--bg-well, #e8e6e4) 72%, transparent);
  }

  .ns-dialog__title {
    margin: 0 0 var(--space-4, 0.49rem);
    color: var(--text-heading, #111);
    font-size: var(--type-lg, 1.25rem);
    font-weight: var(--weight-medium, 500);
    line-height: var(--leading-tight, 1.25);
  }

  .ns-dialog__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--space-3, 0.39rem);
    margin-top: var(--space-7, 0.95rem);
  }

  .ns-dialog__actions form {
    display: contents;
  }
}
